		state.focused = false
		paintStroke(Motion.HOVER_OUT)
		paintIcon(Motion.HOVER_IN)
	end)
	connect(frame.MouseEnter, function()
		state.hovered = true
		paintStroke(Motion.HOVER_IN)
	end)
	connect(frame.MouseLeave, function()
		state.hovered = false
		paintStroke(Motion.HOVER_OUT)
